<span class="line"><span style="color:#F97583;">WHERE</span><span style="color:#E1E4E8;"> user </span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;"> &#39;&#39;</span><span style="color:#E1E4E8;">;</span></span>
